/* English overlay for the Genesis static mirror.
 * Translates UI text client-side from a dictionary (i18n-dict.js).
 * Longest-match first; text nodes, placeholders, titles, aria-labels. */
(function(){
  'use strict';
  var D = window.I18N_DICT || {};
  var keys = Object.keys(D).sort(function(a,b){ return b.length - a.length; });
  var map = new Map();
  keys.forEach(function(k){ map.set(k, D[k]); });
  function _tr(s){
    if(!s) return s;
    var t = map.get(s);
    if(t) return t;
    // try trimmed
    var lead = s.match(/^\s*/)[0], trail = s.match(/\s*$/)[0], core = s.trim();
    t = map.get(core);
    if(t) return lead + t + trail;
    // longest-prefix replacements for composed strings
    var out = s, hit = false;
    for(var i=0;i<keys.length;i++){
      var k = keys[i];
      if(k.length >= 2 && out.indexOf(k) !== -1){ out = out.split(k).join(map.get(k)); hit = true; }
      if(out.indexOf('一-鿿')===-1 && !/[一-鿿]/.test(out)) break;
    }
    if(!hit){ out = regexTr(s); if(out!==s) return out; return s; }
    if(/[一-鿿]/.test(out)){ var o2 = regexTr(out); if(o2!==out) return o2; }
    return out;
  }
  function tr(s){ return polish(_tr(s)); }

  // Pattern post-pass for composed counter/unit strings the dictionary cannot enumerate.
  var RULES = [
    [/^\s*序章?\s*$/, 'Prologue'],
    [/^\s*按\s*$/, 'Press '],
    [/^\s*班\s*$/, 'Class'],
    [/^\s*或\s*$/, 'or'],
    [/^\s*人\s*$/, 'people'],
    [/^\s*件\s*$/, 'items'],
    [/^\s*个\s*$/, 'items'],
    [/^\s*次\s*$/, 'times'],
    [/^\s*条\s*$/, 'items'],
    [/^\s*章\s*$/, 'chapters']
  ];
  function regexTr(s){
    for(var i=0;i<RULES.length;i++){ if(RULES[i][0].test(s)) return s.replace(RULES[i][0], RULES[i][1]); }
    var out = s;
    out = out.replace(/第\s*(\d+)\s*[/／]\s*(\d+)\s*节/g, 'Lesson $1/$2');
    out = out.replace(/第\s*(\d+)\s*[/／]\s*(\d+)\s*幕/g, 'Act $1 / $2');
    out = out.replace(/第\s*(\d+)\s*幕/g, 'Act $1');
    out = out.replace(/第\s*(\d+)\s*节/g, 'Lesson $1');
    out = out.replace(/(\d+)\s*节/g, '$1 lessons');
    out = out.replace(/(\d+)\s*章/g, '$1 chapters');
    out = out.replace(/(\d+)\s*页/g, '$1 pages');
    out = out.replace(/(\d+)\s*分/g, '$1 min');
    out = out.replace(/(\d+)\s*条/g, '$1 items');
    out = out.replace(/(\d+)\s*源/g, '$1 sources');
    out = out.replace(/(\d+)\s*人/g, '$1 people');
    out = out.replace(/(\d+)\s*件/g, '$1 items');
    out = out.replace(/(\d+)\s*次/g, '$1 times');
    out = out.replace(/(\d+)\s*个/g, '$1');
    out = out.replace(/(\d+)\s*[–-]\s*(\d+)\s*岁/g, '$1-$2');
    out = out.replace(/(\d+)\s*岁/g, 'Ages $1');
    out = out.replace(/([A-Za-z])量/g, '$1 count');
    out = out.replace(/按(?=")/g, 'By ');
    return out;
  }

  // Hand-authored meaning overrides (win over dictionary via later Map.set).
  var OVERRIDES = {
    '都是被“一个动作”改出来的': 'All come from applying “one action”',
    '都是被\"一个动作\"改出来的': 'All come from applying “one action”',
    '这五样东西，': 'These five things - ',
    '这 5 件东西，': 'These five things - ',
    '共同点是什么？': 'what do they have in common?',
    '共同点是什么': 'what do they have in common?',
    '只需要带来一个问题、一点好奇,或者一个大胆的"如果"。': 'just bring a question, a bit of curiosity, or a bold “what if”.',
    '“如果”。': 'a bold “what if”.',
    '探索者': 'Explorer',
    '你还没有完成的作品。': 'You do not have a finished invention yet.',
    '先去发明一件,再回来开讲。': 'Invent one first, then come back to pitch it.',
    '选一件作品': 'Pick a work',
    '选一种讲法': 'Pick a style',
    '⚡ 一键预览': '⚡ One-tap preview',
    '不提问,直接按风格骨架出稿并进入演示。先看看效果。': 'No questions - a draft is generated straight from the style template and opened as a preview. Try it first.',
    '推荐': 'Recommended',
    '✦ 精细打磨': '✦ Careful polish',
    '逐页审稿:哪一页要补什么,就在那一页下面补,改完再审,直到没问题。': 'Review page by page: add whatever a page needs right below it, then review again until it is clean.',
    '素材只来自你自己的操作记录：原话逐字引用,方案来自推演记录,数字来自市场模拟。素材里没有的,会做成「待你查证」页。 生成一次讲稿扣 2500 创作币。': 'Material comes only from your own activity: quotes are verbatim, plans come from your reasoning record, numbers from the market simulation. Anything missing becomes a "to be verified" page. Generating one pitch deck costs 2500 creation coins.',
    '我生成的讲稿': 'My generated pitch decks',
    '有图': 'with image',
    '无图': 'no image',
    '分': 'pts',
    '加载失败：': 'Load failed: '
  };
  Object.keys(OVERRIDES).forEach(function(k){ map.set(k, OVERRIDES[k]); });
  // Output polish for translated English: punctuation, spacing, brand repair.
  function polish(out){
    if(!out || /[一-鿿]/.test(out)) return out;
    out = out.replace(/\bSend FaXiaoMing\b/g, 'FaXiaoMing');
    out = out.replace(/\bSent (?:to|by) (?:Fa)?[Xx]iao\s?[Mm]ing\b/g, 'FaXiaoMing');
    out = out.replace(/([A-Za-z0-9!?)"”])。(?=\s|$)/g, '$1.');
    out = out.replace(/([a-z]),(?=[A-Z])/g, '$1, ');
    out = out.replace(/([a-z])"(?=[A-Z“])/g, '$1" ');
    return out;
  }
  // Canvas text (share cards and other exported images) never touches the DOM,
  // so dictionary sweeps cannot reach it; translate fillText arguments at draw time.
  try{
    var _ft = CanvasRenderingContext2D.prototype.fillText;
    CanvasRenderingContext2D.prototype.fillText = function(text, x, y, maxWidth){
      try{ text = tr(String(text)); }catch(e){}
      return (maxWidth === undefined) ? _ft.call(this, text, x, y) : _ft.call(this, text, x, y, maxWidth);
    };
  }catch(e){}

  // Mobile layout repair for cramped page headers.
  function injectCss(){
    if(document.getElementById('i18n-css')) return;
    var st=document.createElement('style'); st.id='i18n-css';
    st.textContent='@media (max-width:640px){.bar{flex-wrap:wrap;height:auto;min-height:0;row-gap:4px;padding:6px 10px}.bar .brand small{display:none}.bar .crumb{min-width:0;flex:1 1 auto}.bar .crumb .lt{display:none}.bar .bar-right{margin-left:auto;flex-wrap:nowrap}.bar .auth{font-size:11px;padding:4px 8px}}';
    (document.head||document.documentElement).appendChild(st);
  }

  // Interim image replacement: restores English imagery for two images whose
  // binaries could not be replaced through the available repo-edit path.
  var IMG_BANNER = 'data:image/jpeg;base64,';
  var IMG_PAYCODE = 'data:image/jpeg;base64,';
  var GAL_STATE = 0; // 0 = not requested, 1 = loading, 2 = loaded
  function loadGalleryMaps(){
    if(GAL_STATE !== 0) return;
    GAL_STATE = 1;
    var done = 0;
    ['i18n-gallery-a.js','i18n-gallery-b.js'].forEach(function(f){
      var sc = document.createElement('script');
      sc.src = f;
      sc.onload = function(){ if(++done === 2){ GAL_STATE = 2; try{ sweep(document.documentElement); }catch(e){} } };
      (document.head || document.documentElement).appendChild(sc);
    });
  }
  function fixImages(root){
    var imgs=(root&&root.querySelectorAll)?root.querySelectorAll('img'):document.querySelectorAll('img');
    var needGal = false;
    imgs.forEach(function(im){
      var s=im.getAttribute('src')||'';
      if(s.indexOf('roadshow-banner.webp')!==-1) im.setAttribute('src',IMG_BANNER);
      if(s.indexOf('assets-shoukuan.jpg')!==-1) im.setAttribute('src',IMG_PAYCODE);
      var a=im.getAttribute('alt')||'';
      if(a==='收款码') im.setAttribute('alt','Demo payment code (simulation only)');
      if(a==='路演大师') im.setAttribute('alt','Roadshow Master');
      // Home gallery posters: replace Chinese-artwork images with English demo artwork.
      if(s.indexOf('api-imgcache-')!==-1){
        var G = window.I18N_GAL_IMG;
        if(G){
          var fn = s.split('/').pop().split('?')[0];
          if(G[fn]) im.setAttribute('src', G[fn]);
        } else { needGal = true; }
      }
    });
    if(needGal) loadGalleryMaps();
  }
  var SKIP = {SCRIPT:1,STYLE:1,CODE:1,PRE:1,IFRAME:1,SVG:1,CANVAS:1};
  function walkText(root){
    var w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, { acceptNode:function(n){
      if(!n.nodeValue || !/[一-鿿]/.test(n.nodeValue)) return NodeFilter.FILTER_REJECT;
      var p = n.parentNode;
      if(!p || SKIP[p.tagName]) return NodeFilter.FILTER_REJECT;
      return NodeFilter.FILTER_ACCEPT;
    }});
    var batch=[], n;
    while((n=w.nextNode()) && batch.length<400){ batch.push(n); }
    batch.forEach(function(x){ var v = tr(x.nodeValue); if(v!==x.nodeValue) x.nodeValue = v; });
  }
  function walkAttrs(root){
    var els = root.querySelectorAll ? root.querySelectorAll('[placeholder],[title],[alt],[aria-label],[value]') : [];
    els.forEach(function(el){
      ['placeholder','title','alt','aria-label'].forEach(function(a){
        var v = el.getAttribute(a);
        if(v && /[一-鿿]/.test(v)){ var nv = tr(v); if(nv!==v) el.setAttribute(a,nv); }
      });
      if(/^(INPUT|TEXTAREA|OPTION|SELECT)$/.test(el.tagName)){
        var v = el.getAttribute('value');
        if(v && /[一-鿿]/.test(v)){ var nv = tr(v); if(nv!==v) el.setAttribute('value',nv); }
      }
    });
  }
  
  function walkElements(root){
    var els = (root.querySelectorAll ? root.querySelectorAll('*') : []);
    var arr = Array.prototype.slice.call(els).filter(function(el){
      if(SKIP[el.tagName]) return false;
      var tc = (el.textContent||'').trim();
      if(!(tc && /[一-鿿]/.test(tc) && map.has(tc))) return false;
      if(el.children.length===0) return true;
      return /^(H[1-4]|TITLE|HEADER|NAV|FOOTER)$/.test(el.tagName) || /hero|title|logo/i.test(el.className||'');
    });
    arr.sort(function(a,b){ return b.compareDocumentPosition(a) & Node.DOCUMENT_POSITION_CONTAINED_BY ? 1 : -1; });
    var done = [];
    arr.forEach(function(el){
      for(var i=0;i<done.length;i++){ if(done[i].contains(el)) return; }
      var tc = el.textContent.trim(); var t = map.get(tc);
      if(t){ el.textContent = t; done.push(el); }
    });
  }
  function walkValues(root){
    var els = root.querySelectorAll ? root.querySelectorAll('input,textarea') : [];
    els.forEach(function(el){
      var v = el.value;
      if(v && /[一-鿿]/.test(v)){ var nv = tr(v); if(nv!==v) el.value = nv; }
    });
  }
  function sweep(root){ injectCss(); fixImages(root); try{ (root.querySelectorAll?root.querySelectorAll('#rs-body .sc'):[]).forEach(function(el){ el.textContent = el.textContent.replace(/分/g,'pts'); }); }catch(e){} walkElements(root); walkText(root); walkAttrs(root); walkValues(root); if(document.documentElement) { var t=tr(document.title||''); if(t!==document.title) document.title=t; } }
  var scheduled=false;
  // Flash-free dynamic translation: handle each mutation synchronously (mutation
  // callbacks run before paint), so injected or per-character typed Chinese never
  // reaches the screen. The debounced full sweep below stays for element-level fixes.
  var INTRO_PAIRS = null;
  function introPairs(){
    if(INTRO_PAIRS) return INTRO_PAIRS;
    INTRO_PAIRS = [];
    var srcs = [
      '每一个改变世界的产品,都曾经只是一个不被相信的想法。',
      '今天,让我们陪你,把它变成现实。'
    ];
    for(var i=0;i<srcs.length;i++){ var t = map.get(srcs[i]); if(t) INTRO_PAIRS.push([srcs[i], t]); }
    return INTRO_PAIRS;
  }
  function typewriterTr(v){
    // A typed prefix of a known intro line: show the matching slice of its translation.
    var pairs = introPairs();
    for(var i=0;i<pairs.length;i++){
      var k = pairs[i][0];
      if(v.length >= 1 && v.length < k.length && k.indexOf(v) === 0){
        var t = pairs[i][1];
        var n = Math.max(1, Math.round(t.length * v.length / k.length));
        return t.slice(0, n);
      }
    }
    return null;
  }
  function syncNode(n){
    var v = n.nodeValue;
    if(!v || !/[一-鿿]/.test(v)) return;
    var p = n.parentNode;
    if(!p || SKIP[p.tagName]) return;
    // Intro typewriter: a partial typed line must translate as a proportional slice
    // of the full line's translation, not as a composed substring mix.
    if(p.closest && p.closest('.intro-type')){
      var lead = v.match(/^\s*/)[0], trail = v.match(/\s*$/)[0], core = v.trim();
      var full = map.get(core);
      if(full){ n.nodeValue = lead + full + trail; return; }
      var pt = typewriterTr(core);
      if(pt){ n.nodeValue = lead + pt + trail; return; }
    }
    var t = tr(v);
    if(t && t !== v) n.nodeValue = t;
  }
  function syncAttr(el, name){
    var v = el.getAttribute(name);
    if(v && /[一-鿿]/.test(v)){ var nv = tr(v); if(nv !== v) el.setAttribute(name, nv); }
  }
  var mo = new MutationObserver(function(muts){
    try{
      for(var i=0;i<muts.length;i++){
        var m = muts[i];
        if(m.type === 'characterData'){ syncNode(m.target); }
        else if(m.type === 'childList'){
          for(var j=0;j<m.addedNodes.length;j++){
            var an = m.addedNodes[j];
            if(an.nodeType === 3) syncNode(an);
            else if(an.nodeType === 1 && !SKIP[an.tagName]){ walkText(an); walkAttrs(an); }
          }
        }
        else if(m.type === 'attributes' && m.target && m.target.getAttribute){ syncAttr(m.target, m.attributeName); }
      }
    }catch(e){}
    if(scheduled) return; scheduled=true;
    setTimeout(function(){ scheduled=false; try{ sweep(document.documentElement); }catch(e){} }, 120);
  });
  function start(){ sweep(document.documentElement); mo.observe(document.documentElement,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['placeholder','title','alt','aria-label','value']}); document.documentElement.lang='en'; }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',start); else start();
  setInterval(function(){ try{walkValues(document);}catch(e){} }, 800);
  window.I18N_TR = tr;
})();
